initJs:
function(container, apiUrl, tables) {
  // 予測結果データを保持
  let currentPredictionData = [];
  let allProductForecasts = [];

  // 店舗データを店舗選択に設定
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品別予測一覧の再描画
  function renderProductForecasts(forecasts) {
    const tbody = container.querySelector('#product-forecast-tbody');
    tbody.innerHTML = forecasts.map(forecast => `
      <tr data-id="${forecast.予測結果ID}">
        <td>${forecast.商品コード || '-'}</td>
        <td>${forecast.商品名 || '-'}</td>
        <td>${forecast.予測対象日 ? new Date(forecast.予測対象日).toLocaleDateString('ja-JP') : '-'}</td>
        <td>${forecast.予測数量 || 0}</td>
        <td>${forecast.推奨発注数量 || 0}</td>
        <td>${forecast.予測精度 || 0}%</td>
        <td>
          <span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; background: ${
            forecast.予測ステータス === '完了' ? 'rgba(34, 197, 94, 0.1)' :
            forecast.予測ステータス === '算出中' ? 'rgba(59, 130, 246, 0.1)' :
            'rgba(239, 68, 68, 0.1)'
          }; color: ${
            forecast.予測ステータス === '完了' ? '#22c55e' :
            forecast.予測ステータス === '算出中' ? '#3b82f6' :
            '#ef4444'
          };">
            ${forecast.予測ステータス || '未処理'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${forecast.予測結果ID}">詳細</button>
          <button class="action-btn secondary order-btn" data-id="${forecast.予測結果ID}">発注</button>
        </td>
      </tr>
    `).join('');
  }

  // 予測結果グラフの描画
  function drawPredictionChart(data) {
    const canvas = container.querySelector('#prediction-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスをクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // グラフエリアの設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // サンプルデータ（実際のデータがない場合）
    const sampleData = data.length > 0 ? data : [
      { date: '2024-01-01', actual: 120, predicted: 115 },
      { date: '2024-01-02', actual: 135, predicted: 140 },
      { date: '2024-01-03', actual: 98, predicted: 105 },
      { date: '2024-01-04', actual: 156, predicted: 150 },
      { date: '2024-01-05', actual: 142, predicted: 138 },
      { date: '2024-01-06', actual: 167, predicted: 165 },
      { date: '2024-01-07', actual: 189, predicted: 185 }
    ];

    // 最大値を取得
    const maxValue = Math.max(...sampleData.map(d => Math.max(d.actual || 0, d.predicted || 0))) * 1.1;

    // 軸の描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // グリッドライン
    ctx.strokeStyle = '#2d3748';
    ctx.lineWidth = 0.5;
    for (let i = 1; i <= 5; i++) {
      const y = padding + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(canvas.width - padding, y);
      ctx.stroke();
    }

    // データポイントの描画
    const pointSpacing = chartWidth / (sampleData.length - 1);

    // 実績データ（青線）
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    sampleData.forEach((point, index) => {
      const x = padding + index * pointSpacing;
      const y = canvas.height - padding - (point.actual / maxValue) * chartHeight;
      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 予測データ（オレンジ線）
    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 2;
    ctx.beginPath();
    sampleData.forEach((point, index) => {
      const x = padding + index * pointSpacing;
      const y = canvas.height - padding - (point.predicted / maxValue) * chartHeight;
      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#e2e8f0';
    ctx.font = '12px sans-serif';
    ctx.fillText('実績値', padding + 20, 30);
    ctx.fillText('予測値', padding + 80, 30);

    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(padding, 22, 15, 3);
    ctx.fillStyle = '#f59e0b';
    ctx.fillRect(padding + 60, 22, 15, 3);
  }

  // 比較チャートの描画
  function drawComparisonChart() {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // サンプル比較データ
    const categories = ['食品', '飲料', '日用品', '冷凍食品', 'その他'];
    const actualData = [450, 320, 280, 180, 150];
    const predictedData = [440, 335, 275, 185, 145];

    const maxValue = Math.max(...actualData, ...predictedData) * 1.1;
    const barWidth = chartWidth / categories.length / 3;

    // 軸の描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // バーチャートの描画
    categories.forEach((category, index) => {
      const x = padding + (chartWidth / categories.length) * index + barWidth;

      // 実績バー
      const actualHeight = (actualData[index] / maxValue) * chartHeight;
      ctx.fillStyle = '#3b82f6';
      ctx.fillRect(x, canvas.height - padding - actualHeight, barWidth, actualHeight);

      // 予測バー
      const predictedHeight = (predictedData[index] / maxValue) * chartHeight;
      ctx.fillStyle = '#f59e0b';
      ctx.fillRect(x + barWidth + 5, canvas.height - padding - predictedHeight, barWidth, predictedHeight);

      // カテゴリ名
      ctx.fillStyle = '#e2e8f0';
      ctx.font = '11px sans-serif';
      ctx.fillText(category, x, canvas.height - padding + 15);
    });
  }

  // 影響要因分析の表示
  function renderFactorAnalysis() {
    const tbody = container.querySelector('#factor-tbody');
    const factors = [
      { factor: '気温', impact: '高', correlation: '0.75', description: '高温時に飲料の需要が増加' },
      { factor: '降水量', impact: '中', correlation: '-0.45', description: '雨天時に外出関連商品が減少' },
      { factor: '週末', impact: '高', correlation: '0.68', description: '土日に食品需要が増加' },
      { factor: 'イベント', impact: '中', correlation: '0.52', description: '地域イベント時に特定商品が増加' }
    ];

    tbody.innerHTML = factors.map(factor => `
      <tr>
        <td>${factor.factor}</td>
        <td>
          <span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; background: ${
            factor.impact === '高' ? 'rgba(239, 68, 68, 0.1)' :
            factor.impact === '中' ? 'rgba(245, 158, 11, 0.1)' :
            'rgba(34, 197, 94, 0.1)'
          }; color: ${
            factor.impact === '高' ? '#ef4444' :
            factor.impact === '中' ? '#f59e0b' :
            '#22c55e'
          };">
            ${factor.impact}
          </span>
        </td>
        <td>${factor.correlation}</td>
        <td>${factor.description}</td>
      </tr>
    `).join('');
  }

  // 予測実行処理
  async function executePrediction() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const seasonalModel = container.querySelector('#seasonal-model').checked;
    const eventModel = container.querySelector('#event-model').checked;
    const weatherModel = container.querySelector('#weather-model').checked;

    // バリデーション
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }
    if (!category) {
      alert('商品カテゴリを選択してください');
      return;
    }
    if (!startDate || !endDate) {
      alert('予測期間を設定してください');
      return;
    }
    if (new Date(startDate) >= new Date(endDate)) {
      alert('開始日は終了日より前の日付を入力してください');
      return;
    }
    if (new Date(startDate) < new Date()) {
      alert('開始日は現在日以降の日付を設定してください');
      return;
    }
    if (!seasonalModel && !eventModel && !weatherModel) {
      alert('予測モデルを選択してください');
      return;
    }

    // ローディング表示
    container.querySelector('#loading-overlay').classList.remove('hidden');

    try {
      // 予測結果を生成（実際のAPIがない場合のサンプル）
      await new Promise(resolve => setTimeout(resolve, 2000)); // 2秒待機

      // 商品データを取得
      const productTable = tables.find(t => t.tableName === '商品マスタ');
      const products = productTable ? productTable.records.filter(p => 
        p.有効フラグ && p.AI予測対象フラグ
      ) : [];

      // 予測結果データを生成
      const forecastResults = products.slice(0, 10).map(product => ({
        予測結果ID: `pred-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        店舗ID: storeId,
        商品ID: product.商品ID,
        商品コード: product.商品コード,
        商品名: product.商品名,
        予測対象日: startDate,
        予測数量: Math.floor(Math.random() * 200) + 50,
        推奨発注数量: Math.floor(Math.random() * 180) + 40,
        予測精度: Math.floor(Math.random() * 30) + 70,
        予測ステータス: '完了',
        予測モデルバージョン: 'v2.1.0',
        発注済フラグ: false
      }));

      allProductForecasts = forecastResults;

      // 予測精度指標を更新
      const avgAccuracy = Math.floor(forecastResults.reduce((sum, f) => sum + f.予測精度, 0) / forecastResults.length);
      container.querySelector('#accuracy-value').textContent = `${avgAccuracy}%`;
      container.querySelector('#confidence-interval').textContent = `±${Math.floor(avgAccuracy * 0.1)}%`;
      container.querySelector('#model-version').textContent = 'AI予測モデル v2.1.0';

      // 外部要因情報を更新
      container.querySelector('#events-list').textContent = 'セール期間、地域祭り';
      container.querySelector('#weather-forecast').textContent = '晴れ時々曇り、最高気温25℃';

      // グラフを描画
      drawPredictionChart([]);
      drawComparisonChart();

      // 影響要因分析を表示
      renderFactorAnalysis();

      // 商品別予測一覧を表示
      renderProductForecasts(allProductForecasts);

      // 結果エリアを表示
      container.querySelector('#prediction-results').classList.remove('hidden');
      container.querySelector('#product-forecast-list').classList.remove('hidden');

    } catch (error) {
      alert('予測処理中にエラーが発生しました: ' + error.message);
    } finally {
      container.querySelector('#loading-overlay').classList.add('hidden');
    }
  }

  // CSVエクスポート
  function exportToCSV() {
    if (allProductForecasts.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測対象日', '予測数量', '推奨発注数量', '予測精度', 'ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allProductForecasts.map(forecast => [
        forecast.商品コード || '',
        `"${forecast.商品名 || ''}"`,
        forecast.予測対象日 || '',
        forecast.予測数量 || 0,
        forecast.推奨発注数量 || 0,
        `${forecast.予測精度 || 0}%`,
        forecast.予測ステータス || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 商品検索
  function searchProducts() {
    const keyword = container.querySelector('#product-search').value.toLowerCase();
    const filtered = allProductForecasts.filter(forecast => 
      (forecast.商品名 || '').toLowerCase().includes(keyword) ||
      (forecast.商品コード || '').toLowerCase().includes(keyword)
    );
    renderProductForecasts(filtered);
  }

  // 初期化
  loadStores();

  // 今日の日付を開始日に設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#start-date').value = today;

  // 1週間後を終了日に設定
  const nextWeek = new Date();
  nextWeek.setDate(nextWeek.getDate() + 7);
  container.querySelector('#end-date').value = nextWeek.toISOString().split('T')[0];

  // イベントリスナー
  container.querySelector('#btn-predict').addEventListener('click', executePrediction);
  container.querySelector('#btn-product-search').addEventListener('click', searchProducts);
  container.querySelector('#btn-export-csv').addEventListener('click', exportToCSV);

  // 商品検索のEnterキー対応
  container.querySelector('#product-search').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      searchProducts();
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const orderBtn = e.target.closest('.order-btn');

    if (detailBtn) {
      const forecastId = detailBtn.dataset.id;
      // 詳細画面への遷移（実装例）
      alert(`予測結果詳細: ${forecastId}`);
    }

    if (orderBtn) {
      const forecastId = orderBtn.dataset.id;
      // 発注画面への遷移
      window.showScreen('scr-1778591852463'); // 発注管理画面
    }
  });
}
